/* @autogenerated */
import { BulkEditField } from 'app/shared/toolkit/bulk-edit/bulk-edit.model';
import { SnippetRepository } from 'app/features/template/snippet/repository/snippet-repository.service';
import { BaseBulkEditAction } from 'app/shared/toolkit/action/base-bulk-edit-action';
import { BulkEditDialogData } from 'app/shared/toolkit/bulk-edit/bulk-edit-dialog.component';
import { Snippet } from 'app/features/template/snippet/model/snippet.model';
import { Component, inject } from '@angular/core';

/** Edición masiva de snippet: los campos que se pueden cambiar en bloque. */
@Component({ selector: 'snippet-view-bulk-edit-action', standalone: false, template: '' })
export class SnippetViewBulkEditActionComponent extends BaseBulkEditAction<Snippet> {
  readonly name = 'bulkEdit';
  protected readonly scope = 'template/snippet';
  protected readonly repository = inject(SnippetRepository);

  protected override keyOf(item: Snippet): string {
    return String(item.uid);
  }

  /** Los campos que se pueden editar en bloque y el tipo de cada uno. */
  protected bulkFields(): readonly BulkEditField<Snippet>[] {
    return [
      { name: 'code', label: this.text('fieldCode'), type: 'text' },
      { name: 'tenant', label: this.text('fieldTenant'), type: 'relation', optional: true },
    ];
  }

  protected override toDialogData(count: number): BulkEditDialogData<Snippet> {
    return {
      title: this.text('dialogTitle'),
      count,
      singular: this.text('selectedSingular'),
      plural: this.text('selectedPlural'),
      confirm: this.text('confirm'),
      cancel: this.text('cancel'),
      fields: this.bulkFields(),
    };
  }
}
